#include <iostream>

using std::cout;
using std::endl;

int main()
{
    int iArray[5] = { 10, 20, 30, 40, 50 };

    int iSum = 0;

    for (int i = 0; i < 5; i++)
    {
        cout << iArray[i] << " ";
        iSum += iArray[i];
    }
    cout << endl;

    cout << iSum << endl;

    return 0;
}

