#include <iostream>

using std::cout;
using std::endl;

int main()
{
    int iTest[5][14] = {};

    for (int i = 0; i < sizeof(iTest) / sizeof(int); i++)
    {
        iTest[i / 14][i % 14] = i;
    }

    for (int y = 0; y < 5; y++)
    {
        for (int x = 0; x < 14; x++)
        {
            cout << iTest[y][x] << "\t";
        }
        cout << endl;
    }

    return 0;
}
